var PI=Math.PI;
function rect(w,h){return {area:w*h,perimeter:2*(w+h)};}
function square(s){return {area:s*s,perimeter:4*s};}
function circle(r){return {area:PI*r*r,circumference:2*PI*r,diameter:2*r};}
