function trapezoid(a,b,h){return {area:(a+b)/2*h};}
function ellipse(a,b){return {area:PI*a*b};}
function regularPolygon(sides,side){var area=(sides*side*side)/(4*Math.tan(PI/sides));return {area:area,perimeter:sides*side};}
